begin;
select plan(6);
select has_function('public'::name, 'publish_course_version'::name);
select ok(exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'course_modules' and policyname = 'modules_insert_manager'), 'module authoring policy exists');
select ok(exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'course_lessons' and policyname = 'lessons_insert_manager'), 'lesson authoring policy exists');
insert into auth.users(id) values ('00000000-0000-0000-0000-000000000041');
insert into public.organizations(id, name, slug, kind) values ('10000000-0000-0000-0000-000000000041', 'Authoring Org', 'authoring-org', 'company');
insert into public.memberships(id, user_id, organization_id, status) values ('20000000-0000-0000-0000-000000000041', '00000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000041', 'active');
insert into public.membership_roles(membership_id, role) values ('20000000-0000-0000-0000-000000000041', 'manager');
set local role authenticated;
set local request.jwt.claim.sub = '00000000-0000-0000-0000-000000000041';
insert into public.courses(id, organization_id, owner_type, title, slug, license_confirmed, created_by) values ('40000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000041', 'organization', 'Authoring', 'authoring', true, '00000000-0000-0000-0000-000000000041');
insert into public.course_versions(id, course_id, version_no, title, license_confirmed, learning_mode) values ('50000000-0000-0000-0000-000000000041', '40000000-0000-0000-0000-000000000041', 1, 'Authoring', true, 'self_paced');
insert into public.course_modules(id, course_version_id, position, title) values ('60000000-0000-0000-0000-000000000041', '50000000-0000-0000-0000-000000000041', 0, 'Module');
insert into public.course_lessons(module_id, position, title) values ('60000000-0000-0000-0000-000000000041', 0, 'Lesson');
select is((select count(*)::integer from public.course_lessons where module_id = '60000000-0000-0000-0000-000000000041'), 1, 'manager can author lesson');
select is(public.publish_course_version('50000000-0000-0000-0000-000000000041'), '50000000-0000-0000-0000-000000000041'::uuid, 'manager can publish non-empty licensed version');
select is((select status from public.courses where id = '40000000-0000-0000-0000-000000000041'), 'published', 'course becomes published');
select * from finish();
rollback;
